SELECT id , title , content , source , url , published_at FROM news_article WHERE published_at >= DATE_SUB(#{date}, INTERVAL 1 DAY) AND published_at < DATE_ADD(#{date}, INTERVAL 2 DAY) AND (
title LIKE CONCAT('%', #{kw}, '%') OR content LIKE CONCAT('%', #{kw}, '%')
) ORDER BY ABS(TIMESTAMPDIFF(MINUTE, published_at, #{closeAt})) LIMIT 5
